 const sourceDialog=document.createElement('dialog');sourceDialog.className='bb-source-dialog';sourceDialog.setAttribute('aria-labelledby','bbSourceTitle');document.body.append(sourceDialog);let sourceTarget=null;
 const helpDialog=document.createElement('dialog');helpDialog.className='bb-help-dialog';helpDialog.setAttribute('aria-labelledby','bbHelpTitle');
 helpDialog.innerHTML=`<header><div><p>GUIDA ALLA BASETTA</p><h2 id="bbHelpTitle">Come leggere la breadboard</h2></div><button data-bb-help-close autofocus aria-label="Chiudi guida alla breadboard">Chiudi ×</button></header><div class="bb-help-content"><p class="bb-help-intro">La breadboard collega i terminali senza saldature. I fori sono collegati da lamelle interne: vicinanza e incroci dei fili, da soli, non creano un contatto.</p><figure><svg viewBox="0 0 680 225" role="img" aria-labelledby="bbHelpDiagramTitle bbHelpDiagramDesc" xmlns="http://www.w3.org/2000/svg"><title id="bbHelpDiagramTitle">Due file e quattro barre della breadboard</title><desc id="bbHelpDiagramDesc">I cinque fori da a2 a e2 sono collegati tra loro, separati da f2 fino a j2. La fila 1 è separata dalla fila 2. Le quattro barre laterali sono indipendenti e collegate in verticale.</desc><rect x="1" y="1" width="678" height="223" rx="12" fill="#eeeee2" stroke="#c8d0c0"/><rect x="315" y="46" width="50" height="150" rx="5" fill="#d7dbcc"/>${[50,82,598,630].map((x,i)=>`<path d="M${x} 65V185" stroke="${i%2?'#2867d8':'#d93545'}" stroke-width="7" opacity=".6"/><text x="${x}" y="32" text-anchor="middle" font-size="13" fill="#344b43">${['L1','L2','R1','R2'][i]}</text>${[75,110,145,180].map(y=>`<circle cx="${x}" cy="${y}" r="5" fill="#fff" stroke="#66775f"/>`).join('')}`).join('')}<path d="M145 145H285" stroke="#287c50" stroke-width="9" opacity=".5"/><path d="M395 145H535" stroke="#ad7828" stroke-width="9" opacity=".5"/>${[...'abcdefghij'].map((c,i)=>{const x=i<5?145+i*35:395+(i-5)*35;return `<text x="${x}" y="65" font-size="14" text-anchor="middle" fill="#344b43">${c}</text>${[100,145].map(y=>`<circle data-bb-help-hole="${c}${y===145?2:1}" cx="${x}" cy="${y}" r="6" fill="#fff" stroke="${y===145?(i<5?'#287c50':'#ad7828'):'#66775f'}" stroke-width="2"/>`).join('')}`}).join('')}<text x="115" y="105" font-size="14" fill="#344b43">1</text><text x="115" y="150" font-size="14" fill="#344b43">2</text><text x="215" y="201" font-size="14" text-anchor="middle" fill="#23633f">a2–e2: collegati</text><text x="465" y="201" font-size="14" text-anchor="middle" fill="#80581c">f2–j2: collegati</text><text x="340" y="217" font-size="11" text-anchor="middle" fill="#53654b">Canale: nessun contatto</text></svg><figcaption>Esempio delle prime due file. Ogni gruppo evidenziato è un collegamento interno distinto.</figcaption></figure><section class="bb-help-examples"><h3>Prova a seguire due fori</h3><div role="group" aria-label="Esempi di contatti della breadboard"><button data-bb-help-case="row">a2 e e2</button><button data-bb-help-case="column">a1 e a2</button><button data-bb-help-case="channel">e2 e f2</button></div><p data-bb-help-answer role="status">Scegli una coppia: i due fori vengono evidenziati nel disegno.</p></section><div class="bb-help-grid"><section><h3>1. Coordinate dei fori</h3><p>La lettera indica la colonna, il numero la fila: <strong>e12</strong> è il foro della colonna e, fila 12. Nel montaggio c’è sempre una sola basetta, da 30 o 63 file. Nei file esportati il prefisso <strong>M1:</strong> identifica questa stessa basetta.</p></section><section><h3>2. Gruppi da cinque</h3><p>Sulla stessa fila, <strong>a–e sono collegati</strong> tra loro e <strong>f–j sono collegati</strong> tra loro. Il canale centrale separa i due gruppi. Due file vicine sono indipendenti: a2 non è collegato ad a3.</p></section><section><h3>3. Barre laterali</h3><p><strong>L1, L2, R1 e R2</strong> sono quattro barre indipendenti, collegate in verticale. Nel modello ciascuna è continua; nessuna è già a massa o alimentata. Lo diventa con un cavo. Su una basetta reale controlla eventuali interruzioni delle barre prima di usarla.</p></section><section><h3>4. Componenti e operazionali</h3><p>I due capi di una resistenza o di un condensatore devono raggiungere gruppi distinti: inserirli nello stesso gruppo li cortocircuita. L’operazionale attraversa il canale centrale. Con la tacca in alto, i pin 1–4 scendono a sinistra e 5–8 risalgono a destra; nel TL082 V− è il pin 4 e V+ il pin 8.</p></section><section><h3>5. Fili, colori e incroci</h3><p>Un ponticello unisce i gruppi dei suoi due fori. <strong>Un incrocio nel disegno non è un contatto.</strong> Verde: ingresso; arancio: uscita; nero: GND; rosso e blu: V+ e V−. I colori aiutano a seguire i nodi; i contatti sono definiti dai fori e dai cavi.</p></section><section><h3>6. Seguire un collegamento</h3><p>Attiva <strong>Vista → Contatti interni</strong> per vedere le lamelle. Clicca un componente, scegli <strong>A/B o un pin</strong>, poi una destinazione: il percorso evidenzia le lamelle tratteggiate e i ponticelli continui. Il passaggio <strong>Componenti</strong> nasconde i cavi, ma mantiene il circuito completo nel calcolo.</p></section><section><h3>7. Dallo schema al componente reale</h3><p>Uno <strong>stesso nodo</strong> dello schema può occupare più gruppi di fori, uniti da ponticelli. Segui il nome e il colore del nodo, poi i due estremi evidenziati. Un punto di giunzione collega i rami nello schema; l’incrocio tra due tratti senza giunzione li lascia separati. La posizione grafica del componente non cambia il suo collegamento elettrico.</p></section><section><h3>8. Esempio: una resistenza verso massa</h3><p>Inserisci i due capi in <strong>e8 e f8</strong>: il canale centrale tiene separati i due gruppi. Se la barra R2 è stata collegata al riferimento GND, un ponticello tra <strong>j8 e R2</strong> porta a massa anche f8, perché f8–j8 condividono la stessa lamella. Il capo in e8 resta sull’altro nodo. È un esempio didattico: nella prova usa i punti evidenziati dal programma.</p></section><section><h3>9. Pinout del TL082</h3><p>Guarda l’integrato dall’alto, con tacca o riferimento in alto. Le due sezioni A e B hanno ingressi e uscite distinti, ma condividono l’alimentazione.</p><table><caption>TL082 a 8 pin · vista dall’alto</caption><thead><tr><th>Pin</th><th>Funzione</th><th>Pin</th><th>Funzione</th></tr></thead><tbody><tr><td>1</td><td>Uscita A</td><td>8</td><td>V+</td></tr><tr><td>2</td><td>Ingresso − A</td><td>7</td><td>Uscita B</td></tr><tr><td>3</td><td>Ingresso + A</td><td>6</td><td>Ingresso − B</td></tr><tr><td>4</td><td>V−</td><td>5</td><td>Ingresso + B</td></tr></tbody></table><p><strong>GND e V− sono diversi:</strong> con alimentazione ±15 V, GND è 0 V e V− è −15 V. I condensatori di bypass vicino all’integrato collegano le alimentazioni al riferimento comune.</p></section><section><h3>10. Generatore e oscilloscopio</h3><p>Il generatore porta il segnale al nodo IN e il ritorno al GND comune. Una sonda misura la differenza tra il puntale e la propria massa: CH1 e CH2 del disegno mostrano anche il nodo misurato. Mantieni corrispondenti attenuazione ×1/×10 e accoppiamento DC/AC nel software e sullo strumento.</p></section><section><h3>11. Usare la costruzione guidata</h3><p>Premi <strong>Costruzione guidata</strong>. Ogni Avanti mostra un pezzo o un collegamento: il passaggio corrente è nitido, il resto è sbiadito. I contrassegni numerati individuano i fori o i connettori da usare. <strong>Mostra i punti</strong> li riporta in vista; Indietro permette di rivedere il passaggio precedente. Pausa e Riprendi conservano il passo. Lo stato Montato o Controllato si registra separatamente. L’indice permette di scegliere un’operazione e filtrare per componente; puoi consultare liberamente il disegno e tornare al passo. Appunti, controlli e misure restano nel progetto.</p></section><section><h3>12. Controllare un collegamento dubbio</h3><p>A circuito spento, puoi verificare con il tester la continuità tra due fori dello stesso gruppo e l’isolamento dei gruppi vicini. Controlla anche le interruzioni delle barre reali. Un segnale sempre nullo può dipendere da un terminale nello stesso gruppo dell’altro; un’uscita bloccata richiede di ricontrollare alimentazione, massa e retroazione.</p></section></div><p class="bb-help-tip"><strong>Per montare:</strong> segui Componenti → Alimentazione → Generatore → Sonde. <strong>Banco intero</strong> e <strong>Primo piano basetta</strong> cambiano solo l’inquadratura, in qualunque passaggio.</p></div>`;
 document.body.append(helpDialog);
 helpDialog.addEventListener('click',event=>{if(event.target.closest('[data-bb-help-close]'))helpDialog.close();const choice=event.target.closest('[data-bb-help-case]');if(!choice)return;const examples={row:{holes:['a2','e2'],text:'a2 ed e2 sono collegati internamente: appartengono allo stesso gruppo da cinque, anche senza un filo.'},column:{holes:['a1','a2'],text:'a1 e a2 sono separati: la stessa lettera non collega due file diverse. Serve un ponticello.'},channel:{holes:['e2','f2'],text:'e2 e f2 sono separati dal canale centrale. Un componente tra questi fori collega due nodi distinti.'}},example=examples[choice.dataset.bbHelpCase];for(const b of helpDialog.querySelectorAll('[data-bb-help-case]'))b.setAttribute('aria-pressed',String(b===choice));for(const hole of helpDialog.querySelectorAll('[data-bb-help-hole]')){const selected=example.holes.includes(hole.dataset.bbHelpHole);hole.setAttribute('r',selected?'9':'6');hole.classList.toggle('bb-help-chosen',selected);}helpDialog.querySelector('[data-bb-help-answer]').textContent=example.text;});
