 const checkDialog=document.createElement('dialog');checkDialog.className='bb-lab-dialog';checkDialog.setAttribute('aria-labelledby','bbLabTitle');
 checkDialog.innerHTML='<header><div><h2 id="bbLabTitle">Controllo al banco</h2><p>Stati e note sono conferme manuali del tuo montaggio.</p></div><div class="bb-lab-header-actions"><button data-bb-lab-export>Scarica scheda</button><button data-bb-lab-close aria-label="Chiudi controllo al banco">Chiudi ×</button></div></header><div class="bb-lab-tabs" role="group" aria-label="Schede del controllo al banco"><button data-bb-lab-tab="assembly" aria-pressed="true">Montaggio</button><button data-bb-lab-tab="measure" aria-pressed="false">Punti di misura</button></div><div class="bb-lab-filters"><label>Stato<select data-bb-lab-filter="status"><option value="">Tutti</option><option value="pending">Da completare o ricontrollare</option>'+Object.entries(A.statuses).map(([v,l])=>'<option value="'+v+'">'+l+'</option>').join('')+'</select></label><label>Gruppo<select data-bb-lab-filter="phase"><option value="">Tutti i gruppi</option>'+LL.phases.map((l,i)=>'<option value="'+i+'">'+l+'</option>').join('')+'</select></label><label>Componente<select data-bb-lab-filter="part"></select></label><label>Cerca<input type="search" data-bb-lab-filter="search" placeholder="Componente, pin o foro"></label></div><p data-bb-lab-summary role="status"></p><p data-bb-lab-error role="alert"></p><div data-bb-lab-rows></div>';
