 function inspectOperation(key){const step=constructionPlan.find(s=>A.itemKey(s)===key);if(!step)return;if(checkDialog.open)checkDialog.close();if(construction.active){construction.active=false;saveConstruction();}state.step=3;drawGeometry();choose(step.kind,step.id);root.querySelector('.bb-board-wrap').scrollIntoView({block:'start'});}
