  for(const el of root.querySelectorAll('.bb-board [data-bb-pin]')){const at=el.dataset.bbPin.lastIndexOf(':'),pin=model.devicePins.find(p=>p.component===el.dataset.bbPin.slice(0,at)&&p.number===Number(el.dataset.bbPin.slice(at+1)));el.classList.toggle('bb-muted',Boolean(focused&&pin&&!nodes.has(pin.node)));}
  for(const el of root.querySelectorAll('.bb-schema [data-bb-net]')){const n=model.nets.find(n=>n.id===el.dataset.bbNet);el.classList.toggle('bb-muted',Boolean(focused&&!nodes.has(n?.index)));}
