  const html=trace?`<span><i></i>${esc(trace.from.label)} · ${esc(shortHole(trace.from.hole))}</span><b>→</b><span>${esc(trace.to.label)} · ${esc(shortHole(trace.to.hole))}</span>${clear}`:cable?`<span><i></i>${esc(cable.a.label)}</span><b>→</b><span>${esc(cable.b.label)}</span>${clear}`:state.part?`<strong>${esc(state.part)}</strong><span>${part?.type==='U'?'Clicca un pin per seguirne il collegamento.':'Clicca A o B per seguire un terminale.'}</span>${clear}`:net?`<span><i></i>Rete ${esc(net.name)}</span>${clear}`:'<span>Seleziona un componente, poi il terminale da seguire.</span>';
  if(strip.innerHTML!==html)strip.innerHTML=html;drawInspection(trace,terms);
