 function input(label,key,value,unit='',factor=1){return`<label>${esc(label)}<div class="bb-input-unit"><input data-bb-field="${esc(key)}" data-factor="${factor}" type="text" inputmode="decimal" value="${Number((value/factor).toPrecision(10))}" aria-label="${esc(label)}"><span>${esc(unit)}</span></div></label>`;}
