  host.innerHTML='<h3>Collegamenti</h3><p>Scegli un cavo o un componente.</p>'+(model.context.params?.type==='difference'?select('Ingressi','drive',model.context.params.drive,[['independent','CH1 e CH2 indipendenti'],['v1','V1 attivo · V2 a massa'],['v2','V2 attivo · V1 a massa'],['common','Modo comune'],['differential','Differenziale']])+'<button data-bb-command="apply-drive">Applica</button>':'');
