  sourceTarget={id,context:contextKey,modelKey,field,owner:ownerKey()};sourceDialog.innerHTML=`<form novalidate><div class="bb-dialog-heading"><h2 id="bbSourceTitle">${esc(title)}</h2><button type="button" data-bb-cancel aria-label="Chiudi generatore">×</button></div><div class="bb-source-fields">${editFields(id)}</div><p class="bb-field-error" role="alert"></p><div class="bb-dialog-actions"><button type="button" data-bb-cancel>Annulla</button><button type="submit" class="bb-primary">Applica</button></div></form>`;sourceDialog.style.setProperty('--bb-channel-color',source?(channel===1?B.palette.input:B.palette.input2):B.palette.positive);waveVisibility();
