 window.BreadboardWorkbench={selectedPart:()=>model?.doc.components.some(c=>c.id===state.part)?state.part:null,editOwner:el=>el.closest('.bb-source-dialog')?sourceTarget?.id:state.part,contextId:()=>contextKey,restoreQuantity:(id,key,value,context)=>{if(context!==contextKey||!Number.isFinite(value))return false;try{return commitChanges({[key]:value},id);}catch(error){message(error.message,true);return false;}},centerSelected:()=>{const el=[...root.querySelectorAll('.bb-board [data-bb-part]')].find(el=>el.dataset.bbPart===state.part);if(!el)return false;el.scrollIntoView({block:'center',inline:'center'});return true;},selectPart:id=>{if(!finishDraft())return false;choose('part',id);return true;},refresh,prepare:finishDraft,isActive:enabled,setMode,snapshot:()=>model?{sectionsPerChip:model.sectionsPerChip,packages:M.clone(model.packages||[]),doc:M.clone(model.doc),pinHoles:M.clone(model.pinHoles),wires:M.clone(model.wires),equivalent:B.verify(model).length===0}:null};refresh();
